/// How `dlls/msvcp120_app/msvcp120_app.spec` exports a name, from the `@ <kind>` column.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ExportKind {
    /// `@ cdecl`: a `__cdecl` function. Forwards to `msvcp120`.
    Cdecl,
    /// `@ thiscall`: a `__thiscall` member function. Forwards to `msvcp120`.
    Thiscall,
    /// `@ extern`: a data export, such as a vtable or a static object. Forwards to `msvcp120`.
    Extern,
    /// `@ stub`: raises `EXCEPTION_WINE_STUB` through [`crate::wine_spec_unimplemented_stub`].
    Stub,
}

/// The `-arch=` value on an export line, spelled as the spec writes it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Arch {
    Arm,
    I386,
    Win32,
    Win64,
}

/// One line of the `msvcp120_app.spec` export table.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Export {
    pub name: &'static str,
    pub kind: ExportKind,
    /// `None` when the line has no `-arch=` flag, so it applies to every architecture.
    pub arch: Option<Arch>,
    /// The argument types between the parentheses, for example `ptr ptr`. Empty when there are none.
    pub args: &'static str,
}

/// Where a forwarded export goes: a function of the same name in `FORWARD_MODULE`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Forward {
    pub module: &'static str,
    pub function: &'static str,
}

/// The module every forwarded export points to, from the `msvcp120.` prefix of each line.
pub const FORWARD_MODULE: &str = "msvcp120";

